def audited(action: str):
    """Label service actions without changing their call signatures."""
    def decorate(operation):
        @wraps(operation)
        def wrapped(service, *args, **kwargs):
            service.events.append(action)
            return operation(service, *args, **kwargs)
        return wrapped
    return decorate

